CREATE PROCEDURE [${dbxschemaname}].[insertApplyForDebitCardMFAScenario]
AS
BEGIN
SET NOCOUNT ON;

	IF(SELECT count(*) from [${dbxschemaname}].[mfa] where [App_id]='RETAIL_AND_BUSINESS_BANKING' AND [Action_id] = 'CARD_MANAGEMENT_APPLY_FOR_DEBIT_CARD' ) = 0  BEGIN 
    END  
DELETE from [${dbxschemaname}].[mfa] where [App_id] = '' and [Action_id] = '';
END
GO

EXEC  [${dbxschemaname}].[insertApplyForDebitCardMFAScenario];
DROP PROCEDURE IF EXISTS [${dbxschemaname}].[insertApplyForDebitCardMFAScenario];
GO
UPDATE [${dbxschemaname}].[featureaction] SET [isMFAApplicable] = '1', [MFA_id] = '1283611941' WHERE ([id] = 'CARD_MANAGEMENT_APPLY_FOR_DEBIT_CARD');
